#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto apply=[&](int x,int y){
        ops.push_back({x,y});
        vector<int> np(n);
        for(int i2=0;i2<y;i2++) np[i2]=p[n-y+i2];
        for(int i2=y;i2<n-x;i2++) np[i2]=p[x+i2-y];
        for(int i2=n-x;i2<n;i2++) np[i2]=p[i2-(n-x)];
        p=np;
    };
    auto pos=[&](int v)->int{for(int k=0;k<n;k++)if(p[k]==v)return k;return -1;};
    for(int i=0;i<n-1;i++){
        int j=pos(i+1);
        if(j==i) continue;
        if(n<=2){break;}
        // Bring to position 0
        if(j>0 && j<n-1) apply(j,n-1-j); // works since j+(n-1-j)=n-1<n
        else if(j==n-1) apply(1,1); // brings pos n-1 to pos 0
        j=pos(i+1);
        if(j==i) continue;
        // Now at position 0, bring to position i
        if(i==0) continue;
        if(i==1){apply(1,1);j=pos(i+1);if(j==i)continue;if(j==0){int x2=n-2;apply(x2,1);}continue;}
        apply(n-i,1);
    }
    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
